insert into public.course_content_draft (course_id, what_you_build, what_you_learn, session, starter_code, test_it_out, troubleshooting, resources, tier, change_note)
values (
  21,
  $wyb$A content pipeline that pulls keyword data and the top 10 ranking pages for a target keyword, asks the AI to identify what those pages are missing, generates a gap-aware outline, writes the article section by section, and finishes with SEO meta title, description, and slug -- with hard character limits enforced in code, never trusted to the AI's own count -- exported as a publish-ready Markdown file.$wyb$,
  $wyl$[
  "Pull keyword volume and top-ranking pages from an SEO API, with response parsing tested against fake data before spending a real paid call",
  "Scrape competitor content defensively - a blocked or slow page must never crash the batch",
  "Run a content-gap analysis and parse a forgiving, marker-based reply",
  "Validate a generated outline against a minimum bar instead of writing from anything the AI returns",
  "Write long-form content section by section, with a length guard that flags (not silently accepts) an off-target section",
  "Enforce SEO character limits in code, since asking an LLM to count characters accurately is asking it to do the one thing it's notoriously unreliable at"
]$wyl$::jsonb,
  $sess${
  "model": "Gemini 3.6 Flash or Claude Haiku 4.5 (your choice - see sdt_ai.py setup)",
  "totalTime": "150 min",
  "buildCount": 4,
  "whatYouNeed": [
    "A free Gemini API key (aistudio.google.com/apikey) OR your own Claude/Anthropic API key (console.anthropic.com/settings/keys)",
    "Python 3.10+ installed",
    "A DataForSEO account (pay-as-you-go - keep an eye on usage during development)",
    "One target keyword you actually want to rank for"
  ],
  "outcomes": [
    "Pull keyword data and the top 10 ranking pages for any target keyword",
    "Scrape competitor content without ever crashing the batch over one blocked page",
    "Identify content gaps those pages consistently miss, and validate an outline against a minimum bar before writing from it",
    "Write the article section by section, with a guard that flags an off-target section length",
    "Generate SEO meta title/description/slug with hard character limits enforced in code and export a publish-ready Markdown file"
  ],
  "builds": [
    {
      "number": 1,
      "title": "Pull keyword data and the top-ranking pages",
      "time": "35 min",
      "description": "Know what you're up against before writing anything.",
      "steps": [
        {
          "instruction": "Create `sdt_ai.py` in your project folder with this code. You'll reuse this exact file, unmodified, in every future AI Builder project:",
          "prompt": "\"\"\"\nSocial Dev AI Builder - your connection to the AI.\n\nYou have TWO ways to power this file. Pick ONE and set it in your .env:\n\n  AI_PROVIDER=gemini    -> your own FREE Google Gemini API key\n  AI_PROVIDER=claude    -> your own Claude/Anthropic API key\n\nEvery project in this course calls ask_ai(...) the exact same way no\nmatter which one you pick - this file is the only place that changes.\n\nSETUP - OPTION 1: Gemini (free, no billing needed):\n\n  1. Go to https://aistudio.google.com/apikey and sign in with any Google\n     account. Click \"Create API key\" - free, no card required.\n  2. In the same folder as this file, create a file named exactly: .env\n  3. Put these two lines inside it:\n\n         AI_PROVIDER=gemini\n         GEMINI_API_KEY=paste_your_own_key_here\n\nSETUP - OPTION 2: Claude (if you already have a paid Claude account):\n\n  1. Go to https://console.anthropic.com/settings/keys and create an API\n     key. This needs billing set up on your Anthropic account - it is a\n     separate thing from a claude.ai Pro subscription, and is billed by\n     Anthropic based on what you actually use.\n  2. In your .env file, put these two lines instead:\n\n         AI_PROVIDER=claude\n         ANTHROPIC_API_KEY=paste_your_own_key_here\n\nNever share either key or put it on GitHub - each one is billed to YOUR\naccount. That's it. Every project in this course reuses this same file.\n\"\"\"\n\nimport os\nimport time\n\nimport requests\nfrom dotenv import load_dotenv\n\n# Reads the .env file sitting next to your project and loads your keys.\nload_dotenv()\n\n# Overridable via .env if you ever want to try a different model.\nGEMINI_MODEL = os.environ.get(\"GEMINI_MODEL\", \"gemini-2.5-flash\")\nGEMINI_URL = (\n    f\"https://generativelanguage.googleapis.com/v1beta/models/{GEMINI_MODEL}:generateContent\"\n)\n\nCLAUDE_MODEL = os.environ.get(\"CLAUDE_MODEL\", \"claude-haiku-4-5\")\nANTHROPIC_URL = \"https://api.anthropic.com/v1/messages\"\nANTHROPIC_VERSION = \"2023-06-01\"\n\n# Gemini's free tier occasionally answers 503 (\"model overloaded\") during\n# busy periods - that's not your code being wrong, retrying a couple of\n# times almost always gets a real answer.\nMAX_ATTEMPTS = 3\nRETRY_DELAY_SECONDS = 3\n\n\nclass AIError(Exception):\n    \"\"\"Something went wrong talking to the AI. The message explains what.\"\"\"\n\n\ndef _get_provider():\n    \"\"\"\n    Reads AI_PROVIDER from .env. Falls back to guessing from whichever key\n    is actually present, so forgetting to set AI_PROVIDER explicitly\n    doesn't crash a setup that only has one key configured.\n    \"\"\"\n    provider = os.environ.get(\"AI_PROVIDER\", \"\").strip().lower()\n    if provider in (\"gemini\", \"claude\"):\n        return provider\n\n    if os.environ.get(\"GEMINI_API_KEY\"):\n        return \"gemini\"\n    if os.environ.get(\"ANTHROPIC_API_KEY\"):\n        return \"claude\"\n\n    raise AIError(\n        \"No AI provider configured.\\n\"\n        \"Add ONE of these pairs to your .env file:\\n\\n\"\n        \"    AI_PROVIDER=gemini\\n\"\n        \"    GEMINI_API_KEY=paste_your_free_key_here\\n\\n\"\n        \"  ...or...\\n\\n\"\n        \"    AI_PROVIDER=claude\\n\"\n        \"    ANTHROPIC_API_KEY=paste_your_own_key_here\\n\\n\"\n        \"Get a free Gemini key at https://aistudio.google.com/apikey\"\n    )\n\n\ndef _ask_gemini(prompt, system=None, max_tokens=1000):\n    api_key = os.environ.get(\"GEMINI_API_KEY\")\n    if not api_key:\n        raise AIError(\n            \"AI_PROVIDER is set to gemini but no GEMINI_API_KEY was found.\\n\"\n            \"Get a free key at https://aistudio.google.com/apikey and add \"\n            \"it to .env:\\n\"\n            \"    GEMINI_API_KEY=paste_your_own_key_here\"\n        )\n\n    payload = {\n        \"contents\": [{\"role\": \"user\", \"parts\": [{\"text\": prompt}]}],\n        \"generationConfig\": {\"maxOutputTokens\": max_tokens},\n    }\n    if system:\n        payload[\"systemInstruction\"] = {\"parts\": [{\"text\": system}]}\n\n    last_problem = \"no response\"\n    for attempt in range(MAX_ATTEMPTS):\n        try:\n            response = requests.post(\n                GEMINI_URL, params={\"key\": api_key}, json=payload, timeout=90\n            )\n        except requests.RequestException:\n            raise AIError(\n                \"Could not reach Gemini. Check your internet connection and try again.\"\n            )\n\n        if response.status_code == 503:\n            last_problem = \"Gemini is busy (503 - high demand on the free tier)\"\n            time.sleep(RETRY_DELAY_SECONDS)\n            continue\n\n        if response.status_code == 429:\n            raise AIError(\n                \"Gemini says you've hit the free tier's rate limit. Wait a \"\n                \"minute and try again.\"\n            )\n\n        if response.status_code == 400:\n            raise AIError(\n                f\"Gemini rejected the request - double check your GEMINI_API_KEY \"\n                f\"is correct: {response.text[:300]}\"\n            )\n\n        if response.status_code != 200:\n            raise AIError(\n                f\"Gemini returned an error (status {response.status_code}): {response.text[:300]}\"\n            )\n\n        data = response.json()\n        try:\n            candidate = data[\"candidates\"][0]\n        except (KeyError, IndexError):\n            raise AIError(f\"Unexpected reply from Gemini: {data}\")\n\n        if candidate.get(\"finishReason\") == \"SAFETY\":\n            raise AIError(\"Gemini declined to answer (safety filter). Try rephrasing your prompt.\")\n\n        try:\n            text = candidate[\"content\"][\"parts\"][0][\"text\"]\n        except (KeyError, IndexError):\n            raise AIError(f\"Unexpected reply shape from Gemini: {data}\")\n\n        usage = data.get(\"usageMetadata\", {})\n        return {\n            \"text\": text,\n            \"input_tokens\": usage.get(\"promptTokenCount\"),\n            \"output_tokens\": usage.get(\"candidatesTokenCount\"),\n        }\n\n    raise AIError(\n        f\"Gemini was unavailable after {MAX_ATTEMPTS} tries ({last_problem}). \"\n        \"This happens sometimes on the free tier during high demand - wait \"\n        \"a minute and try again.\"\n    )\n\n\ndef _ask_claude(prompt, system=None, max_tokens=1000):\n    api_key = os.environ.get(\"ANTHROPIC_API_KEY\")\n    if not api_key:\n        raise AIError(\n            \"AI_PROVIDER is set to claude but no ANTHROPIC_API_KEY was found.\\n\"\n            \"Create one at https://console.anthropic.com/settings/keys and \"\n            \"add it to .env:\\n\"\n            \"    ANTHROPIC_API_KEY=paste_your_own_key_here\"\n        )\n\n    payload = {\n        \"model\": CLAUDE_MODEL,\n        \"max_tokens\": max_tokens,\n        \"messages\": [{\"role\": \"user\", \"content\": prompt}],\n    }\n    if system:\n        payload[\"system\"] = system\n\n    try:\n        response = requests.post(\n            ANTHROPIC_URL,\n            headers={\n                \"x-api-key\": api_key,\n                \"anthropic-version\": ANTHROPIC_VERSION,\n                \"Content-Type\": \"application/json\",\n            },\n            json=payload,\n            timeout=90,\n        )\n    except requests.RequestException:\n        raise AIError(\"Could not reach Claude. Check your internet connection and try again.\")\n\n    try:\n        data = response.json()\n    except ValueError:\n        raise AIError(f\"Unexpected reply from Claude (status {response.status_code}).\")\n\n    if response.status_code == 401:\n        raise AIError(\n            \"Claude rejected your ANTHROPIC_API_KEY - double check it was copied correctly.\"\n        )\n\n    if response.status_code == 429:\n        raise AIError(\"Claude says you've hit your rate or usage limit. Wait a moment and try again.\")\n\n    if \"error\" in data:\n        raise AIError(data[\"error\"].get(\"message\", str(data[\"error\"])))\n\n    text = \"\".join(\n        block.get(\"text\", \"\") for block in data.get(\"content\", []) if block.get(\"type\") == \"text\"\n    )\n    usage = data.get(\"usage\", {})\n    return {\n        \"text\": text,\n        \"input_tokens\": usage.get(\"input_tokens\"),\n        \"output_tokens\": usage.get(\"output_tokens\"),\n    }\n\n\ndef ask_ai_detailed(prompt, system=None, max_tokens=1000, project=None):\n    \"\"\"\n    Same as ask_ai, but returns the whole reply as a dict.\n\n        result = ask_ai_detailed(\"Summarise this\", max_tokens=200)\n        print(result[\"text\"])\n    \"\"\"\n    provider = _get_provider()\n    if provider == \"gemini\":\n        return _ask_gemini(prompt, system=system, max_tokens=max_tokens)\n    return _ask_claude(prompt, system=system, max_tokens=max_tokens)\n\n\ndef ask_ai(prompt, system=None, max_tokens=1000, project=None):\n    \"\"\"\n    Send a question to the AI and get the answer back as text.\n\n        answer = ask_ai(\"Write a haiku about Lagos traffic\")\n        print(answer)\n\n    prompt      - what you want the AI to do. This is the important part.\n    system      - optional. Sets the AI's role, e.g. \"You are a careful editor.\"\n    max_tokens  - roughly how long the answer may be. 1000 is plenty for most.\n    project     - unused, kept so call sites read the same across every\n                  project regardless of which AI is behind this file.\n\n    Works identically whichever provider your .env is set to - every\n    project in this course calls this one function and never needs to\n    know which AI is actually answering.\n\n    Returns the AI's answer as a plain string.\n    Raises AIError with a readable message if something is wrong.\n    \"\"\"\n    return ask_ai_detailed(prompt, system=system, max_tokens=max_tokens, project=project)[\"text\"]\n\n\nif __name__ == \"__main__\":\n    # Running this file directly checks that your setup works.\n    print(\"Testing your AI Builder connection...\\n\")\n    try:\n        provider = _get_provider()\n        result = ask_ai_detailed(\"Say hello in exactly five words.\", max_tokens=50)\n        print(f\"Provider: {provider}\")\n        print(\"The AI said:\", result[\"text\"])\n        print(\"\\nYour setup works. You are ready to build.\")\n    except AIError as problem:\n        print(\"Setup problem:\\n\")\n        print(problem)\n",
          "verify": "Don't run it yet - it needs the .env file from the next step first."
        },
        {
          "instruction": "Create `.env` in the same folder with this content, then replace the placeholders with your real keys:",
          "prompt": "# OPTION 1: your own free Gemini key (recommended - no billing needed)\n# Get one free at https://aistudio.google.com/apikey - no credit card needed\nAI_PROVIDER=gemini\nGEMINI_API_KEY=paste_your_own_key_here\n\n# OPTION 2: your own Claude/Anthropic key (comment OPTION 1 out above,\n# uncomment these two lines instead - needs billing set up on your own\n# Anthropic account)\n# Get one at https://console.anthropic.com/settings/keys\n# AI_PROVIDER=claude\n# ANTHROPIC_API_KEY=paste_your_own_key_here\n\n# DataForSEO - pay-as-you-go, sign up at dataforseo.com\nDATAFORSEO_LOGIN=paste_your_login_here\nDATAFORSEO_PASSWORD=paste_your_password_here\n",
          "verify": "Run `python sdt_ai.py` - it should print which provider you're using, then `The AI said: ...`, and end with `Your setup works. You are ready to build.` If you see `No AI provider configured` instead, check that .env sits next to sdt_ai.py and that AI_PROVIDER plus its matching key are both uncommented."
        },
        {
          "instruction": "Create `keywords.py` with this code:",
          "prompt": "\"\"\"\nStep 1 of the SEO Content Writer Agent (part 1).\n\nPulls search volume for your target keyword from DataForSEO. The\nresponse-parsing helper is pure and tested below against a fake\nresponse shaped like DataForSEO's real one; only the live POST needs a\nreal account and spends a real, paid credit.\n\"\"\"\n\nimport requests\n\nDATAFORSEO_URL = \"https://api.dataforseo.com/v3/keywords_data/google_ads/search_volume/live\"\n\n\ndef _parse_search_volume_response(response_json):\n    \"\"\"\n    Pulls the search volume number out of DataForSEO's real (deeply\n    nested) response shape.\n\n        _parse_search_volume_response(fake_response) -> 1600\n\n    Returns None (never raises) if the shape isn't what's expected -\n    DataForSEO returns an error status with no \"result\" at all on a bad\n    request, and this shouldn't crash the whole pipeline over one\n    malformed response.\n    \"\"\"\n    try:\n        tasks = response_json.get(\"tasks\", [])\n        result = tasks[0][\"result\"][0]\n        return result.get(\"search_volume\")\n    except (IndexError, KeyError, TypeError):\n        return None\n\n\ndef get_keyword_data(keyword, login, password):\n    \"\"\"\n    POSTs to DataForSEO and returns the search volume for `keyword`, or\n    None if the response shape is unexpected. Costs a real DataForSEO\n    credit per call - see Build 1's goFurther note on caching results\n    locally during development.\n    \"\"\"\n    payload = [{\"keyword\": keyword, \"location_code\": 2840, \"language_code\": \"en\"}]\n    response = requests.post(DATAFORSEO_URL, json=payload, auth=(login, password), timeout=30)\n    response.raise_for_status()\n    return _parse_search_volume_response(response.json())\n\n\nif __name__ == \"__main__\":\n    # Run this file on its own to check the parsing works - no\n    # DataForSEO account or network call needed:  python keywords.py\n    fake_response = {\"tasks\": [{\"result\": [{\"keyword\": \"ai agents\", \"search_volume\": 1600}]}]}\n    assert _parse_search_volume_response(fake_response) == 1600\n    print(\"Parsed a fake DataForSEO response correctly: search_volume = 1600\")\n\n    print(\"\\nChecking a malformed/empty response doesn't crash...\")\n    assert _parse_search_volume_response({\"tasks\": []}) is None\n    assert _parse_search_volume_response({}) is None\n    print(\"  OK - both returned None instead of raising\")\n\n    print(\"\\nAll checks passed.\")\n",
          "verify": "Run `python keywords.py` (no DataForSEO account or network call needed - this only tests parsing against a fake response). You should see the fake search volume parsed correctly, and an empty/malformed response correctly returning None instead of crashing, ending with `All checks passed.`"
        },
        {
          "instruction": "Create `serp.py` with this code:",
          "prompt": "\"\"\"\nStep 1 of the SEO Content Writer Agent (part 2).\n\nPulls the top 10 organic results for your target keyword. Same\npure/live split as keywords.py.\n\"\"\"\n\nimport requests\n\nSERP_URL = \"https://api.dataforseo.com/v3/serp/google/organic/live/advanced\"\n\n\ndef _parse_serp_response(response_json):\n    \"\"\"\n    Pulls the top organic results out of DataForSEO's real response\n    shape, as [{\"title\": ..., \"url\": ...}, ...].\n\n    Skips any item missing a URL entirely, and skips paid/featured-\n    snippet items that aren't type \"organic\" - this project is\n    specifically about what genuinely RANKS organically, not what Google\n    happens to show above it.\n    \"\"\"\n    try:\n        tasks = response_json.get(\"tasks\", [])\n        items = tasks[0][\"result\"][0].get(\"items\", [])\n    except (IndexError, KeyError, TypeError):\n        return []\n\n    results = []\n    for item in items:\n        if item.get(\"type\") != \"organic\":\n            continue\n        url = item.get(\"url\")\n        if not url:\n            continue\n        results.append({\"title\": item.get(\"title\", \"\").strip(), \"url\": url})\n\n    return results[:10]\n\n\ndef get_top_results(keyword, login, password):\n    \"\"\"POSTs to DataForSEO and returns the top 10 organic results for `keyword`.\"\"\"\n    payload = [{\"keyword\": keyword, \"location_code\": 2840, \"language_code\": \"en\"}]\n    response = requests.post(SERP_URL, json=payload, auth=(login, password), timeout=30)\n    response.raise_for_status()\n    return _parse_serp_response(response.json())\n\n\nif __name__ == \"__main__\":\n    # Run this file on its own to check the parsing works - no\n    # DataForSEO account or network call needed:  python serp.py\n    fake_response = {\n        \"tasks\": [{\"result\": [{\"items\": [\n            {\"type\": \"organic\", \"title\": \"Best AI Agents 2026\", \"url\": \"https://example.com/a\"},\n            {\"type\": \"featured_snippet\", \"title\": \"Should be skipped\", \"url\": \"https://example.com/skip\"},\n            {\"type\": \"organic\", \"title\": \"No URL here\", \"url\": None},\n            {\"type\": \"organic\", \"title\": \"Another Real Result\", \"url\": \"https://example.com/b\"},\n        ]}]}]\n    }\n    results = _parse_serp_response(fake_response)\n    assert len(results) == 2\n    assert results[0][\"title\"] == \"Best AI Agents 2026\"\n    print(\"Parsed\", len(results), \"organic results, correctly skipping the featured snippet and the no-URL item:\")\n    for r in results:\n        print(\" \", r)\n\n    print(\"\\nAll checks passed.\")\n",
          "verify": "Run `python serp.py`. You should see 2 organic results parsed out of 4 fake items, with the featured snippet and the no-URL item correctly skipped, ending with `All checks passed.`"
        },
        {
          "instruction": "Now run both live functions against your real target keyword. Note DataForSEO charges per call, so avoid running this in a loop during development:",
          "prompt": "python -c \"from keywords import get_keyword_data; from serp import get_top_results; import os; from dotenv import load_dotenv; load_dotenv(); login=os.environ['DATAFORSEO_LOGIN']; pw=os.environ['DATAFORSEO_PASSWORD']; print(get_keyword_data('your keyword', login, pw)); [print(r) for r in get_top_results('your keyword', login, pw)]\"",
          "verify": "You should see a search volume number and a list of up to 10 competing article titles/URLs. If you get a 401 or 403, DataForSEO uses HTTP Basic Auth with your login and password, not a bearer token - a common first mistake."
        }
      ],
      "goFurther": "Cache the keyword and SERP results to a local JSON file so you can re-run later builds without re-calling (and re-paying for) the DataForSEO API."
    },
    {
      "number": 2,
      "title": "Scrape competitors and find content gaps",
      "time": "35 min",
      "description": "This is the strategic core - figuring out what to write that others didn't.",
      "steps": [
        {
          "instruction": "Create `scraper.py` with this code:",
          "prompt": "\"\"\"\nStep 2 of the SEO Content Writer Agent (part 1) - fetches a competitor\npage's readable text, same defensive pattern used across this course: a\nblocked or slow page returns \"\" instead of crashing the whole batch.\n\"\"\"\n\nimport re\n\nimport requests\nfrom bs4 import BeautifulSoup\n\nBROWSER_HEADER = {\"User-Agent\": \"Mozilla/5.0 (compatible; SEOContentAgent/1.0)\"}\nNOT_THE_ARTICLE = [\"script\", \"style\", \"nav\", \"footer\", \"header\", \"aside\", \"form\"]\n\n\ndef clean_html_text(html, max_chars=1500):\n    soup = BeautifulSoup(html, \"html.parser\")\n    for junk in soup(NOT_THE_ARTICLE):\n        junk.decompose()\n    text = re.sub(r\"\\s+\", \" \", soup.get_text(separator=\" \")).strip()\n    return text[:max_chars]\n\n\ndef fetch_full_text(url, max_chars=1500):\n    \"\"\"Fetches url and returns cleaned text, or \"\" if anything goes wrong.\"\"\"\n    try:\n        response = requests.get(url, headers=BROWSER_HEADER, timeout=10)\n        response.raise_for_status()\n    except requests.RequestException:\n        return \"\"\n    return clean_html_text(response.text, max_chars=max_chars)\n\n\nif __name__ == \"__main__\":\n    # Run this file on its own to check the parsing works - no network\n    # call needed:  python scraper.py\n    fake_html = \"<html><body><nav>Menu</nav><article><p>Real article content here.</p></article></body></html>\"\n    text = clean_html_text(fake_html)\n    assert \"Menu\" not in text\n    assert \"Real article content\" in text\n    print(\"Cleaned text:\", repr(text))\n\n    print(\"\\nChecking a deliberately bad URL doesn't crash...\")\n    assert fetch_full_text(\"https://this-domain-does-not-exist-12345.example\") == \"\"\n    print(\"  OK - unreachable URL correctly returned '' instead of raising\")\n\n    print(\"\\nAll checks passed.\")\n",
          "verify": "Run `python scraper.py`. You should see fake HTML correctly cleaned down to just the article text, and a deliberately unreachable URL correctly returning '' instead of raising, ending with `All checks passed.`"
        },
        {
          "instruction": "Create `gap_analysis.py` with this code:",
          "prompt": "\"\"\"\nStep 2 of the SEO Content Writer Agent (part 2) - this is the strategic\ncore: figuring out what to write that competitors consistently miss.\n\"\"\"\n\nfrom sdt_ai import ask_ai\n\nMAX_CHARS_PER_ARTICLE = 1500\n\n\ndef build_prompt(keyword, articles):\n    combined = \"\\n\\n\".join(\n        f\"Article: {a['title']}\\n{a['text'][:MAX_CHARS_PER_ARTICLE]}\"\n        for a in articles\n    )\n    return f\"\"\"Below are the top-ranking articles for the keyword \"{keyword}\". Identify\n5-8 SPECIFIC subtopics, questions, or angles these articles consistently\nMISS or cover poorly. Be concrete - not generic advice like \"add more\ndetail\".\n\nFormat your answer EXACTLY like this:\n\n[GAPS]\none gap per line\n[END]\n\nARTICLES:\n{combined}\"\"\"\n\n\ndef parse_gaps(reply):\n    \"\"\"\n    Turns the AI's reply into a list of gap strings, one per line.\n\n    Same forgiving [MARKER] approach used throughout this course.\n    Returns an empty list (not an error) if no [GAPS] section was found\n    at all - main.py can decide whether to proceed with a generic\n    outline or stop and retry.\n    \"\"\"\n    gaps = []\n    current = None\n\n    for raw_line in reply.splitlines():\n        line = raw_line.strip()\n        marker = line.strip(\"[]\").upper()\n        is_marker = line.startswith(\"[\") and line.endswith(\"]\")\n\n        if is_marker and marker == \"END\":\n            break\n        if is_marker and marker == \"GAPS\":\n            current = \"GAPS\"\n            continue\n        if current != \"GAPS\" or not line:\n            continue\n        if line.startswith(\"```\"):\n            continue\n        gaps.append(line.lstrip(\"-* \").strip())\n\n    return gaps\n\n\ndef find_gaps(keyword, articles):\n    \"\"\"\n    The main function. Give it the keyword and a list of {\"title\", \"text\"}\n    scraped articles, get back a list of specific content gaps.\n    \"\"\"\n    prompt = build_prompt(keyword, articles)\n    reply = ask_ai(prompt, max_tokens=800, project=\"seo-content-writer-agent\")\n    return parse_gaps(reply)\n\n\nif __name__ == \"__main__\":\n    # Run this file on its own to check the parsing works - no AI call,\n    # no credits spent:  python gap_analysis.py\n    good_reply = \"\"\"[GAPS]\nNone of the top articles mention pricing for small teams under 5 people\nMost skip how to handle a failed API call mid-workflow\nNo article compares build-vs-buy total cost of ownership\n[END]\"\"\"\n    gaps = parse_gaps(good_reply)\n    assert len(gaps) == 3\n    assert \"pricing for small teams\" in gaps[0]\n    print(\"Parsed\", len(gaps), \"gaps:\")\n    for g in gaps:\n        print(\" -\", g)\n\n    print(\"\\nChecking a reply with no [GAPS] marker at all returns an empty list...\")\n    assert parse_gaps(\"Sorry, I couldn't analyze those articles.\") == []\n    print(\"  OK\")\n\n    print(\"\\nAll checks passed.\")\n",
          "verify": "Run `python gap_analysis.py` (no AI call, no credits spent - this only tests parsing against a fake reply). You should see 3 gaps parsed from a well-formed reply, and a reply with no [GAPS] marker correctly returning an empty list, ending with `All checks passed.`"
        },
        {
          "instruction": "Now run the real pipeline on your top-10 URLs from Build 1:",
          "prompt": "python -c \"from scraper import fetch_full_text; from serp import get_top_results; from gap_analysis import find_gaps; import os; from dotenv import load_dotenv; load_dotenv(); results = get_top_results('your keyword', os.environ['DATAFORSEO_LOGIN'], os.environ['DATAFORSEO_PASSWORD']); articles = [{'title': r['title'], 'text': t} for r in results if (t := fetch_full_text(r['url']))]; print(find_gaps('your keyword', articles))\"",
          "verify": "Some URLs may fail to scrape - that's normal, just check the log for how many succeeded. You should get 5-8 specific, actionable gaps - not generic advice like 'add more detail'."
